def choice[T](self, SEQ: Sequence[T]) -> T:
    """Pick one element from a sequence."""
    if not SEQ:
        msg = "Cannot choose from an empty sequence"
        raise IndexError(msg)

    if len(SEQ) == 1:
        return SEQ[0]

    idx = self.sample_discrete(0, len(SEQ) - 1)
    assert 0 <= idx <= len(SEQ) - 1
    return SEQ[idx]
